def solve_domino_tiling_count(N, forbidden_edge=None):
    """
    Counts the number of perfect matchings (domino tilings) on an N x N grid graph,
    respecting a forbidden edge.
    """
    if N % 2 != 0:
        return 0

    cells = [(r, c) for r in range(N) for c in range(N)]

    # Mapping (r, c) to index 0 to N*N - 1
    coord_to_index = {coord: i for i, coord in enumerate(cells)}

    # Adjacency list for the grid graph
    adj = {}
    for r in range(N):
        for c in range(N):
            u = (r, c)
            adj[u] = []
            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                v = (r + dr, c + dc)
                if 0 <= v[0] < N and 0 <= v[1] < N:
                    # Check for forbidden edge
                    if forbidden_edge is not None:
                        e = tuple(sorted((u, v)))
                        if e == tuple(sorted(forbidden_edge)):
                            continue
                    adj[u].append(v)

    # Backtracking search for perfect matchings
    # We use a set to track matched vertices
    memo = {}

    def count_matchings(unmatched_cells):
        if not unmatched_cells:
            return 1  # Found one complete tiling

        # Use a canonical representation (tuple of sorted cells) for memoization
        state = tuple(sorted(unmatched_cells))
        if state in memo:
            return memo[state]

        # Pick the lexicographically smallest unmatched cell
        u = min(unmatched_cells)
        r_u, c_u = u

        count = 0

        # Try matching u with all available neighbors v
        for v in adj[u]:
            if v in unmatched_cells:
                # Match (u, v)
                new_unmatched = unmatched_cells - {u, v}
                count += count_matchings(new_unmatched)

        memo[state] = count
        return count

    initial_unmatched = set(cells)
    return count_matchings(initial_unmatched)

